import {demo,requireSession,markConnected,identity,api,can} from './server-session.mjs';
import {ServerResources,personalRequestsCsv} from './server-resources.mjs?v=backend-complete-20261104.4';
const server=demo?null:new ServerResources(false);
function lecturerRoute(value){return value==='logs'?'requests':value;}
if(location.hash==='#/logs')location.replace('#/requests');
const staleDraftMessage='Phiếu đã thay đổi ở phiên khác. Nội dung bạn nhập chưa được ghi. Hãy đóng biểu mẫu và mở lại phiếu để xem dữ liệu mới trước khi sửa tiếp.';
if(server){await requireSession();markConnected();}

let serverRouteRevision=0;
async function loadServerRoute(target=route){
 target=lecturerRoute(target);
 const revision=++serverRouteRevision;
 if(!server)return;
 const map={
  overview:[{date:selectedDay},1],
  calendar:[{date:selectedDay},1],
  rooms:[{...roomFilter},pages.rooms],
  devices:[{...deviceFilter},pages.devices],
  requests:[{tab:filterTab,...requestFilter},pages.requests],
  returns:[{...returnFilter,readyPage:pages.returnsReady},pages.returns],
  logs:[{...logFilter,eligiblePage:pages.logsEligible},pages.logs]
 };
 const [filters,page]=map[target]||[{date:selectedDay},1];
 const result=await server.loadLecturerPage(target,filters,page);
 if(revision!==serverRouteRevision)return false;
 db=result;syncCatalog();return true;
}

function installServer(){
 statuses.receipt_disputed=['Sai lệch khi nhận','red'];
 let busy=false;
 async function task(button,work,reload=true){
  if(busy)return;busy=true;if(button)button.disabled=true;
  try{
   await work();
   if(reload){await loadServerRoute(route);closeModal();render();toast('Đã lưu dữ liệu trên máy chủ.');}
  }catch(e){
   if(e.status===401)location.assign('login.html');
   if(e.status===409&&e.code==='STALE_VERSION'){
    const bf=document.querySelector('#booking-form');
    if(bf?.dataset.existing){
     bf.dataset.staleVersion='true';
     const box=document.querySelector('#form-error');
     if(box)box.textContent=staleDraftMessage;
     return;
    }
    await loadServerRoute(route);closeModal();render();toast('Dữ liệu phiếu vừa được cập nhật trên máy chủ. Đã tải lại trạng thái mới nhất.');return;
   }
   const box=document.querySelector('#form-error');if(box)box.textContent=e.message;else toast(e.message);
  }finally{busy=false;if(button)button.disabled=false;}
 }
 const refreshBtn=document.querySelector('#server-refresh');
 if(refreshBtn)refreshBtn.onclick=()=>task(refreshBtn,async()=>{await loadServerRoute(route);render();toast('Đã tải lại dữ liệu màn hình hiện tại.');},false);
 document.addEventListener('click',e=>{
  const button=e.target.closest('button,[data-action]');if(!button)return;const d=button.dataset;
  if(d.confirmCancel||d.confirmReceive){e.preventDefault();e.stopImmediatePropagation();const id=d.confirmCancel||d.confirmReceive;task(button,()=>server.action(id,d.confirmCancel?'cancel':'receipt',d.confirmReceive?Number(document.querySelector('[name=serverReceivedQuantity]')?.value??db.requests.find(r=>r.id===id).quantity):null));}
  else if(d.action==='export'){e.preventDefault();e.stopImmediatePropagation();task(button,async()=>{const profile=await api.me();const rows=await server.loadExportRequests({tab:filterTab,...requestFilter});const csv=personalRequestsCsv(rows,profile,statuses,filterTab);downloadRequests(csv);toast('Đã xuất đầy đủ các phiếu cá nhân khớp bộ lọc và phạm vi quyền xuất hiện tại.');},false);}
  else if(d.action==='help'){e.preventDefault();e.stopImmediatePropagation();modal('Hướng dẫn sử dụng',`<div class="detail-note"><p><strong>1. Đăng ký & sửa nháp:</strong> Chọn phòng hoặc thiết bị, nhập lịch và mục đích rồi lưu nháp hoặc gửi duyệt. Cả bản nháp phòng và thiết bị đều sửa trực tiếp (giữ nguyên mã phiếu và tài sản).</p><p><strong>2. Theo dõi & phân trang:</strong> Dữ liệu tải theo từng màn hình và phân trang từ máy chủ. Khi nhận bàn giao thiết bị, nhập số thực nhận để phản ánh đủ hoặc thiếu.</p><p><strong>3. Trả:</strong> Có thể trả từng phần tốt, hỏng, mất; số lượng kho chỉ cập nhật khi quản lý tiếp nhận.</p><p><strong>4. Thông báo & báo cáo:</strong> Dùng Tải lại dữ liệu để làm mới màn hiện tại; xuất CSV cá nhân theo bộ lọc yêu cầu quyền xuất báo cáo.</p></div><p class="form-note">Đang đăng nhập: ${esc(identity.displayName)} · ${esc(identity.userName)}. Hồ sơ lưu trên máy chủ SQL Server và được kiểm tra quyền cho từng thao tác.</p>`);}
  else if(d.action==='profile'){e.preventDefault();e.stopImmediatePropagation();modal('Hồ sơ tài khoản',`<dl class="detail-grid">${[['Họ và tên',identity.displayName],['Tên đăng nhập',identity.userName],['Email',identity.email],['Đơn vị',(server.departments||[]).find(x=>x.id===identity.departmentId)?.name||identity.departmentId],['Vai trò',identity.roleIds.join(', ')],['Phạm vi tài khoản',({all:'Toàn trường',unit:'Đơn vị hiện tại',units:'Các đơn vị được chỉ định',self:'Cá nhân'})[identity.scope]||identity.scope]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="form-note">Quyền thực tế là giao phạm vi tài khoản và vai trò; các quyền bị từ chối vẫn được áp dụng.</p>`);}
  else if(d.book){e.preventDefault();e.stopImmediatePropagation();task(button,async()=>{await server.ensureResource(d.kind,d.book);db=server.snapshot;syncCatalog();if(d.kind==='room')await server.availability(d.date||roomFilter.date||TODAY,[d.book]);book(d.book,d.kind,null,{date:d.date,start:d.start,end:d.end});},false);}
  else if(d.detail){e.preventDefault();e.stopImmediatePropagation();task(button,async()=>{if(!db.requests.some(x=>x.id===d.detail)){await server.loadRequestById(d.detail);db=server.snapshot;}detail(d.detail);},false);}
  else if(d.edit){e.preventDefault();e.stopImmediatePropagation();task(button,async()=>{const latest=await server.loadRequestById(d.edit);if(!latest||latest.status!=='draft'){await loadServerRoute(route);closeModal();render();throw Error('Phiếu không còn ở trạng thái bản nháp.');}await server.ensureResource(latest.kind,latest.resource);db=server.snapshot;syncCatalog();if(latest.kind==='room')await server.availability(latest.date,[latest.resource]);book(latest.resource,latest.kind,latest);},false);}
  else if(d.tab){e.preventDefault();e.stopImmediatePropagation();filterTab=d.tab;pages.requests=1;task(button,async()=>{await loadServerRoute('requests');render();},false);}
  else if(d.page){e.preventDefault();e.stopImmediatePropagation();const target=d.pageTarget||route;pages[target]=Math.max(1,Number(d.page)||1);task(button,async()=>{await loadServerRoute(route);render();window.scrollTo({top:0});},false);}
  else if(d.day){e.preventDefault();e.stopImmediatePropagation();selectedDay=d.day;task(button,async()=>{await loadServerRoute(route);render();},false);}
  else if(d.action==='clear-room-time'){e.preventDefault();e.stopImmediatePropagation();roomFilter.start='';roomFilter.end='';pages.rooms=1;task(button,async()=>{await loadServerRoute('rooms');render();},false);}
 },true);
 document.addEventListener('submit',e=>{
  const f=e.target;const id=f.getAttribute('id');if(!['booking-form','return-form','resource-filter','list-filter'].includes(id))return;
  e.preventDefault();e.stopImmediatePropagation();
  if(id==='resource-filter')return task(e.submitter,async()=>{if(!syncResourceFilterForm(f))return;pages[route]=1;await loadServerRoute(route);render();},false);
  if(id==='list-filter')return task(e.submitter,async()=>{syncListFilterForm(f);await loadServerRoute(route);render();},false);
  if(id==='booking-form'){if(f.dataset.staleVersion){document.querySelector('#form-error').textContent=staleDraftMessage;return;}const intent=e.submitter?.value||'pending';return task(e.submitter,async()=>{await server.book(f,intent);filterTab=intent==='draft'?'draft':'all';pages.requests=1;closeModal();if(route==='requests'){await loadServerRoute('requests');render();}else location.hash='#/requests';toast(intent==='draft'?'Đã lưu bản nháp trên máy chủ.':'Đã gửi đăng ký xét duyệt.');},false);}
    task(e.submitter,()=>server.return(f));
 },true);
 document.addEventListener('change',e=>{
  if(e.target.id==='calendar-date'&&e.target.value){e.stopImmediatePropagation();selectedDay=e.target.value;task(null,async()=>{await loadServerRoute('calendar');render();},false);return;}
  if(e.target.closest('#list-filter')&&e.target.tagName==='SELECT'){e.stopImmediatePropagation();const lf=e.target.closest('#list-filter');syncListFilterForm(lf);task(null,async()=>{await loadServerRoute(route);render();},false);return;}
  const f=e.target.closest('#resource-filter,#booking-form');if(!f)return;
  if(f.id==='resource-filter'&&e.target.name==='search')return;
  e.stopImmediatePropagation();
  if(f.id==='resource-filter')return task(null,async()=>{if(!syncResourceFilterForm(f))return;pages[route]=1;await loadServerRoute(route);render();},false);
  if(f.dataset.kind==='room')task(null,async()=>{const date=new FormData(f).get('date')||TODAY;await server.availability(date,[f.dataset.resource]);updateBookingAvailability();},false);
 },true);
 new MutationObserver(()=>{
  const b=document.querySelector('[data-confirm-receive]');if(!b||document.querySelector('[name=serverReceivedQuantity]'))return;const r=db.requests.find(r=>r.id===b.dataset.confirmReceive);if(!r)return;const label=document.createElement('label');label.textContent='Số thực nhận (nhập thiếu để báo sai lệch)';const input=document.createElement('input');input.name='serverReceivedQuantity';input.type='number';input.min='0';input.max=String(r.quantity);input.value=String(r.quantity);label.append(input);document.querySelector('#dialog-body').prepend(label);b.textContent='Xác nhận thực nhận';
 }).observe(document.querySelector('#dialog-body'),{childList:true});
}
import { DEFAULT_ROOMS, DEFAULT_DEVICES, createLecturerSeed } from './resource-seed.mjs';
import { normalizeResources, roomReservations, deviceFree } from './resource-store.mjs';
import { ROOM_OPEN, ROOM_CLOSE, minutes, timeAt, overlaps, holdsRoom, freeIntervals, fitsInterval, futureIntervals } from './availability.mjs';
const $ = (s, root = document) => root.querySelector(s);
const paths = {
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2 M8 17h2',
 room:'M4 21V5l11-2v18 M15 7h5v14 M2 21h20 M11 12h.01',
 equipment:'M3 4h18v12H3z M8 21h8 M12 16v5 M6 8h5 M6 11h8',
 file:'M14 3H5v18h14V8z M14 3v5h5 M8 12h8 M8 16h5',
 book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1z M12 5v15',
 help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01',
 graduation:'M2 8l10-5 10 5-10 5z M6 10v6c3 3 9 3 12 0v-6 M22 8v8',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
 chevron:'M8 10l4 4 4-4',arrow:'M4 12h16 M15 7l5 5-5 5',plus:'M12 5v14 M5 12h14',
 clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 6v6l4 2',
 pin:'M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 1 1 14 0z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M22 21v-3a4 4 0 0 0-3-4 M17 2a4 4 0 0 1 0 8',
 check:'M20 6L9 17l-5-5',close:'M6 6l12 12 M6 18L18 6',menu:'M3 6h18 M3 12h18 M3 18h18',
 search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',
 bulb:'M9 18h6 M10 22h4 M8 14a7 7 0 1 1 8 0c-1 1-1 3-1 4H9c0-1 0-3-1-4',
 shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',
 more:'M5 12h.01 M12 12h.01 M19 12h.01',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',
 logout:'M9 3H4v18h5 M10 12h12 M17 7l5 5-5 5',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 11v6 M12 7h.01'
};
const icon = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad = n => String(n).padStart(2,'0');
const today = new Date();
const iso = d => new Date(d.getTime()+7*3600000).toISOString().slice(0,10);
const TODAY = iso(today);
const offsetDate = n => { const d = new Date(today); d.setDate(d.getDate()+n); return iso(d); };
const fmtDate = s => {const [y,m,d] = String(s).split('-'); return `${d}/${m}/${y}`;};
const friendlyDate = today.toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'});
let rooms = structuredClone(DEFAULT_ROOMS), devices = structuredClone(DEFAULT_DEVICES);
const seed = createLecturerSeed;
const KEY = 'hpuni-lecturer-v1';
let storageWarning = '';
let route=lecturerRoute((globalThis.location?.hash||'').replace('#/','')||'overview'), filterTab='all', selectedDay=TODAY;
const roomFilter={date:TODAY,start:'',end:'',search:'',type:'',capacity:0};
const deviceFilter={search:'',type:''};
const requestFilter={search:'',status:''};
const returnFilter={search:''};
const logFilter={search:''};
const pages={rooms:1,devices:1,requests:1,returns:1,returnsReady:1,logs:1,logsEligible:1};
let db={version:1,resourceRevision:0,catalog:{rooms:[],devices:[]},requests:[],logs:[],roomReservations:[]};
if(server)await loadServerRoute(route);else try {const saved = JSON.parse(localStorage.getItem(KEY)); db = saved?.version === 1 && Array.isArray(saved.requests) && Array.isArray(saved.logs) ? saved : seed();} catch {db = seed();storageWarning = 'Không đọc được dữ liệu đã lưu. Đang dùng dữ liệu mẫu trong phiên này.';}
function save(){if(server)throw Error('Dữ liệu thật phải được lưu qua API.');try{db.resourceRevision=(db.resourceRevision||0)+1;localStorage.setItem(KEY,JSON.stringify(db));return true;}catch{toast('Bộ nhớ trình duyệt không khả dụng. Dữ liệu chỉ giữ trong phiên hiện tại.');return false;}}
const statuses = {pending:['Chờ xét duyệt','amber'],approved:['Đã duyệt','green'],draft:['Bản nháp','gray'],cancelled:['Đã hủy','gray'],rejected:['Từ chối','red'],ready:['Chờ nhận thiết bị','blue'],borrowed:['Đang mượn','blue'],return_pending:['Chờ tiếp nhận trả','amber'],completed:['Hoàn tất','green']};
const badge = s => {const [label,color]=statuses[s]||['Không xác định','gray'];return `<span class="badge ${color}">${label}</span>`;};
const menus = [['overview','grid','Tổng quan'],['calendar','calendar','Lịch của tôi'],['rooms','room','Đăng ký phòng'],['devices','equipment','Đăng ký thiết bị'],['requests','file','Phiếu của tôi'],['returns','logout','Trả thiết bị']];
if(!Array.isArray(db.roomReservations)) db.roomReservations=[
 {id:'SHARED-A201-1',kind:'room',resource:'A201',date:TODAY,start:'07:00',end:'08:30',status:'approved'},
 {id:'SHARED-A201-2',kind:'room',resource:'A201',date:TODAY,start:'09:30',end:'11:30',status:'approved'}
];
function roomBusy(id,date,exclude='') {return roomReservations(db,id,date,exclude);}
function roomFree(id,date,exclude='') {return futureIntervals(freeIntervals(roomBusy(id,date,exclude)),date);}
function syncCatalog(){if(server){rooms=db.catalog.rooms;devices=db.catalog.devices;return;}db=normalizeResources(db);rooms=db.catalog.rooms;devices=db.catalog.devices;}
function readLatest(){if(server)return;try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.requests)&&Array.isArray(saved.logs))db=saved;syncCatalog();}catch{}}
syncCatalog();

let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
const arrow = icon('arrow');
function logReviewStatus(l){return `<div><span class="badge ${l.status==='confirmed'?'green':'blue'}">${l.status==='needs_update'?'Cần bổ sung':l.status==='pending'?'Chờ xác nhận':'Đã xác nhận'}</span>${l.reviewNotes?`<p style="margin-top:8px">Ý kiến quản lý: ${esc(l.reviewNotes)}</p>`:''}</div>`;}
function header(eyebrow,title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${action || `<div class="date-pill">${icon('calendar')}${esc(friendlyDate)}</div>`}</div>`;}
function weekStrip(){const d=new Date(`${selectedDay}T12:00:00`);d.setDate(d.getDate()-((d.getDay()+6)%7));let html='';for(let i=0;i<7;i++){const day=new Date(d);day.setDate(d.getDate()+i);const s=iso(day);html+=`<button class="day ${s===selectedDay?'active':''}" data-day="${s}" aria-pressed="${s===selectedDay}">${['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','CN'][i]}<strong>${pad(day.getDate())}</strong><i></i></button>`;}return html;}
function agendaSource(){return server?(db.agendaRequests||db.requests):db.requests;}
function agenda(){const events=agendaSource().filter(r=>r.date===selectedDay&&r.kind==='room'&&r.status==='approved').sort((a,b)=>a.start.localeCompare(b.start));return events.length?events.map((r,i)=>`<div class="agenda-item"><div class="time">${esc(r.start)}<small>${esc(r.end)}</small></div><div class="event-line ${i%2?'blue':''}"></div><div class="event-info"><h3>${esc(r.purpose)}</h3><div class="event-meta"><span>${icon('pin')}${esc(r.name)}</span><span>${icon('users')}${esc(r.students)} sinh viên</span></div></div>${badge(r.status)}<button class="icon-btn table-action" data-detail="${esc(r.id)}" aria-label="Chi tiết ${esc(r.name)}">${icon('chevron')}</button></div>`).join(''):`<div class="empty">${icon('calendar')}<h3>Chưa có lịch sử dụng phòng</h3><p>Không có đăng ký đã duyệt vào ngày ${fmtDate(selectedDay)}.</p><a class="text-link" href="#/rooms">Tìm và đăng ký phòng ${arrow}</a></div>`;}
function pendingTotal(){return server?(db.lecturerSummary?.pendingCount??db.navPendingCount??0):db.requests.filter(r=>r.status==='pending').length;}
function notices(){if(server)return `<div class="notice"><div><strong>${pendingTotal()} phiếu chờ xét duyệt</strong><p>Theo dõi trạng thái trong Phiếu của tôi.</p></div></div>`;return `<div class="notice"><span class="notice-icon">${icon('check')}</span><div><strong>Phòng học của bạn đã sẵn sàng</strong><p>Đăng ký phòng B.201 đã được phê duyệt. Xem lịch để chuẩn bị buổi học.</p><small>Thông báo mẫu · Hôm nay</small></div></div><div class="notice"><span class="notice-icon">${icon('info')}</span><div><strong>Đăng ký nguồn lực trực tuyến</strong><p>Gửi yêu cầu trước buổi học để bộ phận quản lý bố trí nguồn lực.</p><small>Hướng dẫn sử dụng</small></div></div>`;}
function table(requests){return requests.length?`<div class="table-wrap"><table><thead><tr><th>PHIẾU ĐĂNG KÝ</th><th>THỜI GIAN SỬ DỤNG</th><th>LOẠI</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${requests.map(r=>`<tr><td><span class="record-icon">${icon(r.kind==='room'?'room':'equipment')}</span><span class="record-text"><span class="record-name">${esc(r.name)}</span><small class="record-code">${esc(r.id)}</small></span></td><td>${fmtDate(r.date)}<small class="record-code">${esc(r.start)} – ${esc(r.end)}</small></td><td>${r.kind==='room'?'Phòng học':'Thiết bị'}</td><td>${badge(r.status)}</td><td><button class="icon-btn table-action" data-detail="${esc(r.id)}" aria-label="Xem phiếu ${esc(r.id)}">${arrow}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('file')}<h3>Chưa có phiếu phù hợp</h3><p>Thay đổi bộ lọc hoặc tạo một đăng ký mới.</p></div>`;}
function pager(info,target=route){if(!info||info.total<=info.pageSize)return '';const totalPages=Math.max(1,Math.ceil(info.total/info.pageSize)),page=Math.min(Math.max(1,info.page||1),totalPages),from=(page-1)*info.pageSize+1,to=Math.min(info.total,page*info.pageSize);return `<nav class="pagination" aria-label="Phân trang" style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:16px;padding-top:12px;border-top:1px solid rgba(15,40,30,.08);flex-wrap:wrap"><span style="font-size:12px;color:#5c6f63">Hiển thị <strong>${from}–${to}</strong> / <strong>${info.total}</strong> · Trang ${page}/${totalPages}</span><div style="display:flex;gap:8px"><button type="button" class="btn" data-page="${page-1}" data-page-target="${esc(target)}" ${page<=1?'disabled':''}>Trang trước</button><button type="button" class="btn" data-page="${page+1}" data-page-target="${esc(target)}" ${page>=totalPages?'disabled':''}>Trang sau</button></div></nav>`;}
const campusArt=`<svg viewBox="0 0 280 200" aria-hidden="true"><path d="M27 155h232 M52 154V69h161v85 M45 69h176l-88-40z M113 153v-39h34v39 M65 81h23v22H65z M102 81h23v22h-23z M139 81h23v22h-23z M176 81h23v22h-23z M65 117h23v22H65z M176 117h23v22h-23z M129 41h9v16h-9z M66 163h134 M44 171h179 M238 151v-36 M238 92c-15 0-21 13-15 22-9 16 0 25 15 23 18 2 26-10 15-23 6-10-1-22-15-22z M31 150v-22 M31 109c-14 0-19 23 0 23s14-23 0-23z"/><path d="M12 180h253 M213 48l16-9 M224 63l19-2 M25 54l14 10 M33 35l7 12" opacity=".4"/><circle cx="133" cy="53" r="7"/></svg>`;
function overview(){const s=server?db.lecturerSummary:null;const pending=s?s.pendingCount:db.requests.filter(r=>r.status==='pending').length;const active=db.requests.filter(r=>['borrowed','return_pending'].includes(r.status));const todayCount=s?s.todayApproved:db.requests.filter(r=>r.date===TODAY&&r.status==='approved').length;const borrowedCount=s?s.borrowedDevices:active.reduce((n,r)=>n+r.quantity-r.returned,0);const recentRows=server?(db.recentRequests||[]):[...db.requests].reverse().slice(0,4);const dayAgendaCount=agendaSource().filter(r=>r.date===selectedDay&&r.kind==='room'&&r.status==='approved').length;const stats=[['Lịch sử dụng hôm nay',todayCount,'lịch','calendar','<b>Đã được phê duyệt</b>'],['Đăng ký chờ duyệt',pending,'phiếu','clock','<span class="warn">Đang chờ bộ phận quản lý</span>'],['Thiết bị đang mượn',borrowedCount,'thiết bị','equipment','Theo dõi trong Phiếu của tôi']];return `${header('KHÔNG GIAN GIẢNG VIÊN','Tổng quan','Một nơi để quản lý lịch giảng dạy và nguồn lực của bạn.')}<section class="hero"><div class="hero-copy"><div class="hero-tag"><span class="tiny-dot"></span> CHÀO MỪNG TRỞ LẠI</div><h2>Chào ${server?esc(identity.displayName):'thầy Minh Anh'} <span style="font-size:20px">☀</span></h2><p>Sẵn sàng cho một ngày giảng dạy hiệu quả.<br>Đặt phòng, mượn thiết bị và theo dõi mọi đăng ký ngay tại đây.</p><div class="hero-actions"><a class="btn primary" href="#/rooms">${icon('plus')}Đăng ký phòng</a><a class="btn ghost" href="#/devices">${icon('equipment')}Mượn thiết bị ${arrow}</a></div></div><div class="hero-art">${campusArt}</div><div class="hero-note">KẾT NỐI NGUỒN LỰC · NÂNG TẦM TRI THỨC</div></section><section class="stats" aria-label="Thống kê cá nhân">${stats.map(([label,value,unit,ic,foot])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${pad(value)}<span>${unit}</span></div><div class="stat-foot">${foot}</div></div>`).join('')}</section><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Lịch sử dụng của tôi</h2><p>Phòng học và phòng thực hành đã được duyệt</p></div><a href="#/calendar" class="text-link">Xem lịch ${arrow}</a></div><div class="week-label">Tháng ${today.getMonth()+1}, ${today.getFullYear()}</div><div class="week-strip">${weekStrip()}</div><div class="agenda">${agenda()}</div><div class="agenda-foot"><span>${selectedDay===TODAY?'Hôm nay':fmtDate(selectedDay)} · ${dayAgendaCount} lịch sử dụng</span><div class="legend"><span>Phòng máy</span><span>Phòng học</span></div></div></section><aside class="right-column"><section class="panel"><div class="panel-head"><h2>Thông báo <span>${server?pending:'03'}</span></h2><button class="text-link" data-action="notifications">Tất cả ${arrow}</button></div><div class="notice-list">${notices()}</div></section><section class="tip-card"><span class="eyebrow">${icon('bulb')} MẸO NHỎ CHO BẠN</span><h3>Chủ động lịch, trọn buổi dạy</h3><p>Kiểm tra sức chứa và trang thiết bị của phòng trước khi gửi đăng ký để lựa chọn không gian phù hợp.</p><button class="text-link" data-action="help">Tìm hiểu thêm ${arrow}</button></section></aside></div><section class="panel recent"><div class="panel-head"><div><h2>Đăng ký gần đây</h2><p>Theo dõi tiến trình xử lý các yêu cầu của bạn</p></div><a class="text-link" href="#/requests">Xem tất cả ${arrow}</a></div>${table(recentRows)}</section>`;}
function roomArt(){return `<svg viewBox="0 0 140 95" aria-hidden="true"><path d="M15 78V15h110v63 M10 78h120 M40 15v39h60V15 M45 47h49 M35 68h25v10 M80 68h25v10 M32 66v-8h31v8 M77 66v-8h31v8 M24 40v9 M116 40v9 M64 15v7h13v-7"/><path d="M22 85h96 M68 40h8" opacity=".4"/></svg>`;}
function resourcesPage(kind){
 const room=kind==='room';
 const typeOptions=server?(room?db.roomTypes||[]:db.deviceCategories||[]):[...new Set((room?rooms:devices).map(r=>room?r.type:r.category))];
 const selectedType=room?roomFilter.type:deviceFilter.type;
 const searchVal=room?roomFilter.search:deviceFilter.search;
 const cardsHtml=resourceCards(kind,searchVal,selectedType,room?roomFilter.capacity:0);
 const totalCount=server?(server.pageInfo?.total??0):(room?rooms:devices).length;
 const summaryText=server?(room?`${totalCount} phòng còn trống · ${fmtDate(roomFilter.date)}${roomFilter.start?' · '+roomFilter.start+'–'+roomFilter.end:' · Tất cả khung giờ'}`:`${totalCount} nhóm thiết bị phù hợp`):'';
 return `${header(room?'PHÒNG HỌC & THỰC HÀNH':'TRANG THIẾT BỊ','Đăng ký '+(room?'phòng':'thiết bị'),room?'Chọn ngày, xem giờ còn trống và đăng ký khoảng thời gian phù hợp.':'Lựa chọn thiết bị để hỗ trợ giảng dạy và nghiên cứu.')}
 ${room?`<div class="inline-info">Giờ phục vụ: <strong>${ROOM_OPEN}\u2013${ROOM_CLOSE}</strong>. Khung gợi ý có thể chỉnh lại. Phiếu chờ duyệt và đã duyệt đều giữ giờ; bản nháp chưa giữ chỗ.</div>`:''}
 <form class="filter-bar ${room?'room-filter':''}" id="resource-filter">
 <div class="field"><label for="resource-search">${room?'Tên phòng hoặc tòa nhà':'Tên thiết bị'}</label><input id="resource-search" name="search" value="${esc(searchVal)}" placeholder="${room?'Tìm phòng, tòa nhà…':'Tìm máy chiếu, laptop, micro…'}"></div>
 <div class="field"><label for="resource-type">${room?'Loại phòng':'Nhóm thiết bị'}</label><select name="type" id="resource-type"><option value="">Tất cả</option>${typeOptions.map(t=>`<option value="${esc(t)}" ${selectedType===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div>
 ${room?`<div class="field"><label for="capacity">Sức chứa tối thiểu</label><input type="number" id="capacity" name="capacity" min="1" max="500" value="${roomFilter.capacity||''}" placeholder="Số sinh viên"></div><div class="field"><label for="room-date">Ngày sử dụng</label><input id="room-date" type="date" name="date" min="${TODAY}" value="${roomFilter.date}" required></div><div class="field"><label for="room-start">Từ giờ (tùy chọn)</label><input id="room-start" type="time" name="start" min="${ROOM_OPEN}" max="${ROOM_CLOSE}" value="${roomFilter.start}"></div><div class="field"><label for="room-end">Đến giờ (tùy chọn)</label><input id="room-end" type="time" name="end" min="${ROOM_OPEN}" max="${ROOM_CLOSE}" value="${roomFilter.end}"></div>`:''}
 <button class="btn primary" type="submit">${icon('search')}Tìm kiếm</button>${room?'<button class="btn" type="button" data-action="clear-room-time">Xem cả ngày</button>':''}</form>
 <p id="resource-feedback" class="availability-summary" role="status">${esc(summaryText)}</p><div id="resource-result" class="resource-grid">${cardsHtml}</div>${server?pager(server.pageInfo,room?'rooms':'devices'):''}`;
}
function resourceCards(kind,search='',type='',capacity=0){
 const room=kind==='room';
 const date=roomFilter.date;
 const source=room?rooms:devices;
 const list=server?source.filter(r=>!room||(r.available&&roomFree(r.id,date).length&&(!roomFilter.start||!roomFilter.end||fitsInterval(roomFree(r.id,date),roomFilter.start,roomFilter.end)))):source.filter(r=>(!search||`${esc(r.name)} ${r.building||''}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')))&&(!type||(r.type||r.category)===type)&&(!capacity||r.seats>=capacity)&&(!room||(r.available&&roomFree(r.id,date).length&&(!roomFilter.start||!roomFilter.end||fitsInterval(roomFree(r.id,date),roomFilter.start,roomFilter.end)))));
 return list.length?list.map((r,i)=>{
 const free=room?roomFree(r.id,date):[];
 const busy=room?roomBusy(r.id,date):[];
 const selected=room&&roomFilter.start&&roomFilter.end?{start:roomFilter.start,end:roomFilter.end}:null;
 const choice=selected||free[0];
 return `<article class="resource-card" data-room="${room?r.id:''}"><div class="room-visual ${r.visual||(i%2?'lab':'')}">${room?roomArt():`<span style="display:flex;transform:scale(3)">${icon(r.shape)}</span>`}<span class="room-number">${r.id} \u00b7 HPUNI</span><span class="badge green">${room?'Còn khung giờ trống':'Sẵn sàng'}</span></div><div class="resource-body"><h2>${esc(r.name)}</h2><p>${room?`${esc(r.building)} \u00b7 ${esc(r.type)} \u00b7 ${r.seats} chỗ ngồi`:`${esc(r.category)} \u00b7 M\u00e3 ${r.id}`}</p><div class="tags">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>
 ${room?`<div class="room-availability"><strong>${icon('clock')}Giờ còn trống · ${fmtDate(date)}</strong><div class="free-slots">${free.map(g=>`<button class="free-slot" data-book="${r.id}" data-kind="room" data-date="${date}" data-start="${g.start}" data-end="${timeAt(Math.min(minutes(g.start)+50,minutes(g.end)))}" title="Chọn giờ gợi ý; có thể chỉnh lại">${g.start}\u2013${g.end}<small>Gợi ý ${g.start}–${timeAt(Math.min(minutes(g.start)+50,minutes(g.end)))} ${icon('plus')}</small></button>`).join('')}</div>${busy.length?`<details class="busy-details"><summary>${busy.length} lượt đã giữ giờ</summary><p>${busy.sort((a,b)=>a.start.localeCompare(b.start)).map(b=>`${esc(b.start)}\u2013${esc(b.end)} \u00b7 ${b.status==='pending'?'Chờ duyệt':'Đã đặt'}`).join('<br>')}</p></details>`:'<p class="slot-note">Chưa có lượt đặt trong ngày.</p>'}<p class="slot-note">Nhấn khoảng trống để chọn gợi ý 50 phút; có thể chỉnh giờ trong biểu mẫu.</p></div>`:''}
 <div class="resource-bottom"><small>${room?(selected?`Phù hợp ${selected.start}\u2013${selected.end}`:'Chọn khung giờ bên trên'):`${r.available} ${esc(r.unit)} trong danh mục`}</small><button class="btn primary" data-book="${r.id}" data-kind="${kind}" ${room?`data-date="${date}" data-start="${choice.start}" data-end="${selected?choice.end:timeAt(Math.min(minutes(choice.start)+50,minutes(choice.end)))}"`:''}>${room?'Đăng ký phòng':'Đăng ký mượn'} ${arrow}</button></div></div></article>`;
 }).join(''):`<div class="empty full-empty">${icon('calendar')}<h3>${room?'Không còn phòng trống trong khoảng đã chọn':'Không tìm thấy thiết bị'}</h3><p>${room?'Chọn ngày hoặc khoảng giờ khác. Các giờ đã đặt không hiển thị để đăng ký trùng.':'Thử tên khác hoặc giảm điều kiện lọc.'}</p></div>`;
}
function syncResourceFilterForm(form){
 const f=new FormData(form),room=route==='rooms',search=String(f.get('search')||'').trim(),type=String(f.get('type')||''),capacity=Number(f.get('capacity')||0);
 if(!room){Object.assign(deviceFilter,{search,type});return true;}
 Object.assign(roomFilter,{search,type,capacity,date:String(f.get('date')||TODAY),start:String(f.get('start')||''),end:String(f.get('end')||'')});
 const bad=roomFilter.date<TODAY||((roomFilter.start||roomFilter.end)&&!(roomFilter.start&&roomFilter.end&&minutes(roomFilter.start)<minutes(roomFilter.end)))||(roomFilter.start&&minutes(roomFilter.start)<minutes(ROOM_OPEN))||(roomFilter.end&&minutes(roomFilter.end)>minutes(ROOM_CLOSE));
 if(bad){if($('#resource-feedback'))$('#resource-feedback').textContent='Vui lòng chọn ngày hợp lệ và đủ cả hai giờ; giờ kết thúc phải sau bắt đầu, trong 07:00–18:00.';if($('#resource-result'))$('#resource-result').innerHTML='';return false;}
 return true;
}
function syncListFilterForm(form){
 const f=new FormData(form),search=String(f.get('search')||'').trim();
 if(route==='requests'){requestFilter.search=search;requestFilter.status=String(f.get('status')||'');pages.requests=1;}
 else if(route==='returns'){returnFilter.search=search;pages.returns=1;}
 else if(route==='logs'){logFilter.search=search;pages.logs=1;pages.logsEligible=1;}
}
function updateResourceResults(){
 const form=$('#resource-filter');if(!form)return;
 if(!syncResourceFilterForm(form))return;
 const room=route==='rooms';
 readLatest();$('#resource-result').innerHTML=resourceCards(room?'room':'device',room?roomFilter.search:deviceFilter.search,room?roomFilter.type:deviceFilter.type,room?roomFilter.capacity:0);
 $('#resource-feedback').textContent=room?`${$('#resource-result').querySelectorAll('.resource-card').length} phòng còn trống · ${fmtDate(roomFilter.date)}${roomFilter.start?' \u00b7 '+roomFilter.start+'\u2013'+roomFilter.end:' \u00b7 Tất cả khung giờ'}`:'';
}
function returnsPage(){
 const active=server?(db.activeReturnRequests||[]):db.requests.filter(r=>r.kind==='device'&&['borrowed','return_pending'].includes(r.status));
 const ready=server?(db.readyRequests||[]):db.requests.filter(r=>r.kind==='device'&&r.status==='ready');
 const activeTotal=server?(server.pageInfo?.total??active.length):active.length;
 return `${header('MƯỢN & TRẢ THIẾT BỊ','Trả thiết bị','Chọn phiếu đang mượn để trả toàn bộ hoặc một phần thiết bị.')}<div class="inline-info">Bạn có thể khai báo thiết bị tốt, hỏng hoặc mất. Sau khi gửi, phiếu chờ cán bộ quản lý tiếp nhận; số lượng đã trả chưa tự tăng trước khi kiểm tra.</div>${server?`<form class="filter-bar" id="list-filter"><div class="field"><label for="return-search">Tìm phiếu mượn thiết bị</label><input id="return-search" name="search" value="${esc(returnFilter.search)}" placeholder="Mã phiếu, tên thiết bị, mục đích…"></div><button class="btn primary" type="submit">${icon('search')}Lọc</button></form>`:''}<section class="panel"><div class="panel-head"><h2>Thiết bị đang giữ <span>${activeTotal} phiếu</span></h2><a class="text-link" href="#/requests">Tất cả phiếu ${arrow}</a></div>${active.length?active.map(r=>`<article class="return-card"><div class="return-icon">${icon('equipment')}</div><div class="return-info"><h3>${esc(r.name)}</h3><p>${esc(r.id)} · Ngày mượn ${fmtDate(r.date)}</p><div class="return-counts"><span>Đã mượn <b>${r.quantity}</b></span><span>Đã tiếp nhận trả <b>${r.returned||0}</b></span><span>Còn giữ <b>${r.quantity-(r.returned||0)}</b></span></div>${r.returnRequest&&r.status==='return_pending'?`<p class="return-pending">Đã yêu cầu trả ${r.returnRequest.quantity}: ${r.returnRequest.good} tốt, ${r.returnRequest.damaged} hỏng, ${r.returnRequest.lost} mất. Đang chờ tiếp nhận.</p>`:''}</div><div class="return-actions">${badge(r.status)}${r.status==='borrowed'?`<button class="btn primary" data-return="${r.id}">${icon('logout')}Trả thiết bị</button>`:`<button class="btn" data-detail="${r.id}">Xem yêu cầu trả</button>`}</div></article>`).join(''):'<div class="empty">'+icon('check')+'<h3>Không có thiết bị đang giữ</h3><p>Các thiết bị đã nhận sẽ xuất hiện tại đây để bạn gửi yêu cầu trả.</p></div>'}${server?pager(server.pageInfo,'returns'):''}</section>${ready.length?`<section class="panel recent"><div class="panel-head"><h2>Thiết bị chờ xác nhận nhận <span>${server?(server.pageInfo?.readyTotal??ready.length):ready.length} phiếu</span></h2></div>${ready.map(r=>`<div class="log-card"><span>${icon('equipment')}</span><div><h3>${esc(r.name)}</h3><p>${r.quantity} thiết bị · ${esc(r.id)}</p></div><button class="btn" data-receive="${r.id}">Xác nhận đã nhận</button></div>`).join('')}${server?pager({page:server.pageInfo?.readyPage||1,total:server.pageInfo?.readyTotal||0,pageSize:20},'returnsReady'):''}</section>`:''}`;
}
function calendarPage(){return `${header('KẾ HOẠCH CÁ NHÂN','Lịch của tôi','Theo dõi các đăng ký phòng đã được phê duyệt.','<a href="#/rooms" class="btn primary">'+icon('plus')+'Đăng ký phòng</a>')}<section class="panel calendar-page"><div class="panel-head"><div><h2>Lịch sử dụng phòng</h2><p>Chọn một ngày trong tuần để xem chi tiết</p></div><div class="field" style="flex:0 1 170px;min-width:130px"><label for="calendar-date">Chọn ngày</label><input type="date" id="calendar-date" value="${selectedDay}"></div></div><div class="week-strip">${weekStrip()}</div><div class="agenda">${agenda()}</div><div class="agenda-foot"><span>Ngày ${fmtDate(selectedDay)}</span><span>Lịch chờ duyệt hiển thị trong Phiếu của tôi</span></div></section>`;}
function requestsPage(){
 const demoFiltered=db.requests.filter(r=>(filterTab==='all'||(filterTab==='device'||filterTab==='room'?r.kind===filterTab:r.status===filterTab))&&(!requestFilter.status||r.status===requestFilter.status)&&(!requestFilter.search||`${r.id} ${esc(r.name)} ${r.purpose||''}`.toLocaleLowerCase('vi').includes(requestFilter.search.toLocaleLowerCase('vi'))));
 const demoInfo={page:pages.requests,pageSize:20,total:demoFiltered.length};
 const rows=server?db.requests:[...demoFiltered].reverse().slice((pages.requests-1)*20,pages.requests*20);
 const total=server?(server.pageInfo?.total??rows.length):demoFiltered.length;
 const tabCount=v=>server?(db.requestCounts?.[v]??0):db.requests.filter(r=>v==='all'||(v==='room'||v==='device'?r.kind===v:r.status===v)).length;
 return `${header('THEO DÕI ĐĂNG KÝ','Phiếu của tôi','Xem trạng thái, cập nhật bản nháp và xử lý các phiếu của bạn.','<a class="btn primary" href="#/rooms">'+icon('plus')+'Đăng ký mới</a>')}<div class="view-tabs" role="tablist" aria-label="Lọc phiếu">${[['all','Tất cả'],['room','Phòng học'],['device','Thiết bị'],['pending','Chờ duyệt'],['draft','Bản nháp']].map(([v,l])=>`<button class="tab ${filterTab===v?'active':''}" data-tab="${v}" role="tab" aria-selected="${filterTab===v}">${l} <span>(${tabCount(v)})</span></button>`).join('')}</div><form class="filter-bar" id="list-filter"><div class="field"><label for="request-search">Tìm phiếu</label><input id="request-search" name="search" value="${esc(requestFilter.search)}" placeholder="Mã phiếu, phòng/thiết bị, mục đích…"></div><div class="field"><label for="request-status">Trạng thái</label><select id="request-status" name="status"><option value="">Tất cả trạng thái</option>${Object.entries(statuses).map(([k,[label]])=>`<option value="${k}" ${requestFilter.status===k?'selected':''}>${esc(label)}</option>`).join('')}</select></div><button class="btn primary" type="submit">${icon('search')}Lọc</button></form><section class="panel"><div class="panel-head"><h2>Danh sách phiếu <span>${total} phiếu</span></h2><button class="text-link" data-action="export" ${server&&!can('reports.export')?'disabled title="Cần quyền xuất báo cáo"':''}>${icon('download')}Tải CSV</button></div>${table(rows)}${pager(server?server.pageInfo:demoInfo,'requests')}</section><p style="color:#91a095;font-size:10px;margin-top:17px">${server?'Các phiếu của tài khoản hiện tại được phân trang và lọc quyền trực tiếp từ máy chủ. Xuất CSV bao gồm toàn bộ các trang khớp bộ lọc hiện tại (cần quyền xuất báo cáo).':'Chỉ hiển thị các phiếu thuộc tài khoản giảng viên minh họa.'} Nhấn mũi tên để xem chi tiết và thao tác.</p>`;
}
function render(){readLatest();route=lecturerRoute(location.hash.replace('#/','')||'overview');const item=menus.find(m=>m[0]===route);$('#breadcrumb').textContent=item?.[2]||'Không tìm thấy';$('#nav').innerHTML=menus.map(([path,ic,label])=>`<a class="nav-link ${route===path?'active':''}" href="#/${path}" ${route===path?'aria-current="page"':''}>${icon(ic)}${label}${path==='requests'?`<span class="nav-count">${pendingTotal()}</span>`:''}</a>`).join('')+'<div class="nav-section-line"></div><button class="nav-link" style="border:0;background:none;width:100%;text-align:left" data-action="help">'+icon('help')+'Hướng dẫn sử dụng</button>';const views={overview,rooms:()=>resourcesPage('room'),devices:()=>resourcesPage('device'),calendar:calendarPage,requests:requestsPage,returns:returnsPage};$('#main').innerHTML=views[route]?views[route]():header('ĐIỀU HƯỚNG','Không tìm thấy trang','Vui lòng chọn chức năng từ menu.','<a class="btn primary" href="#/overview">Về tổng quan</a>');hydrate();closeMenu();document.title=`${item?.[2]||'Không tìm thấy'} · Giảng viên HPUNI`;}
let previousFocus;
function modal(title,html){previousFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;hydrate($('#dialog'));if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){$('#dialog').close();previousFocus?.focus();}
function error(message){const e=$('#form-error');if(e){e.textContent=message;e.focus();}}
function book(id,kind,existing,suggestion={}){
 if(kind==='room'&&!existing){
  const date=suggestion.date||iso(new Date()),free=roomFree(id,date);
  if(!fitsInterval(free,suggestion.start,suggestion.end)){
   if(!free.length){toast('Ngày này không còn khoảng giờ tương lai còn trống. Hãy chọn ngày khác.');return;}
   suggestion={...suggestion,date,start:free[0].start,end:timeAt(Math.min(minutes(free[0].start)+50,minutes(free[0].end)))};
  }
 }
 const r=(kind==='room'?rooms:devices).find(x=>x.id===id)||(existing?{id,name:existing.name,seats:Math.max(existing.students||30,1),available:Math.max(existing.quantity||1,1),unit:'thiết bị',tags:[]}:null);if(!r)return;if(r.api?.active===false||(!existing&&!r.available)){toast('Nguồn lực này hiện không phục vụ.');return;}const maxCount=kind==='room'?r.seats:Math.max(r.available||0,existing?.quantity||1);modal(existing?'Chỉnh sửa bản nháp':kind==='room'?'Đăng ký sử dụng phòng':'Đăng ký mượn thiết bị',`<p class="form-note"><strong>${esc(r.name)}</strong>${existing?` · Mã phiếu <strong>${esc(existing.id)}</strong>`:''}<br>${kind==='room'?`${r.seats} chỗ${r.tags?.length?' · '+r.tags.map(esc).join(' · '):''}`:`${r.available} ${r.unit||'thiết bị'} trong danh mục. Kiểm tra khả dụng theo khoảng thời gian khi gửi.`}</p><form id="booking-form" data-resource="${esc(id)}" data-kind="${kind}" data-existing="${esc(existing?.id||'')}">${kind==='room'?'<div class="booking-live full" id="booking-availability" role="status"></div>':''}<div class="form-grid"><div class="field full"><label for="book-date">Ngày sử dụng *</label><input id="book-date" type="date" name="date" value="${existing?.date||suggestion.date||TODAY}" min="${TODAY}" required></div><div class="field"><label for="book-start">Bắt đầu *</label><input id="book-start" type="time" name="start" value="${existing?.start||suggestion.start||'08:00'}" required></div><div class="field"><label for="book-end">Kết thúc *</label><input id="book-end" type="time" name="end" value="${existing?.end||suggestion.end||'10:00'}" required></div><div class="field full"><label for="book-count">${kind==='room'?'Số sinh viên':'Số lượng mượn'} *</label><input id="book-count" name="count" type="number" min="1" max="${maxCount}" value="${existing?(existing.students||existing.quantity):(suggestion.count??(kind==='room'?Math.min(30,maxCount):1))}" required></div><div class="field full"><label for="book-purpose">Mục đích sử dụng (không bắt buộc)</label><textarea id="book-purpose" name="purpose" maxlength="300" placeholder="Tên học phần, lớp hoặc hoạt động…">${esc(existing?.purpose||suggestion.purpose||'')}</textarea></div><label class="check-field full"><input name="commitment" type="checkbox" required><span>Tôi cam kết sử dụng đúng mục đích, bảo quản và bàn giao nguồn lực theo đăng ký.</span></label></div><p class="error" id="form-error" tabindex="-1" role="alert"></p><div class="form-actions"><button type="submit" name="intent" value="draft" formnovalidate class="btn">Lưu nháp</button><button type="submit" name="intent" value="pending" class="btn primary">Gửi đăng ký ${arrow}</button></div></form>`);if(kind==='room')updateBookingAvailability();}
function updateBookingAvailability(){
 const form=$('#booking-form');if(!form||form.dataset.kind!=='room')return;
 const f=new FormData(form),date=String(f.get('date')),start=String(f.get('start')),end=String(f.get('end'));
 readLatest();const free=roomFree(form.dataset.resource,date,form.dataset.existing);
 const valid=date>=TODAY&&fitsInterval(free,start,end);
 const submit=form.querySelector('[name="intent"][value="pending"]');if(submit)submit.disabled=!valid;
 const target=$('#booking-availability');target.classList.toggle('unavailable',!valid);
 target.innerHTML=`<strong>${valid?icon('check')+' Khoảng giờ đã chọn còn trống':icon('clock')+' Khoảng giờ này không khả dụng'}</strong><p>Giờ còn trống ${fmtDate(date)}: ${free.length?free.map(i=>i.start+'\u2013'+i.end).join(' \u00b7 '):'Không còn giờ trống'}</p><small>Gợi ý được điền sẵn; bạn có thể chỉnh ngày và giờ bên dưới.</small>`;
}
function bookingSubmit(form,intent){readLatest();const f=new FormData(form);const kind=form.dataset.kind;const resource=(kind==='room'?rooms:devices).find(r=>r.id===form.dataset.resource);if(!resource?.available)return error('Nguồn lực hiện không khả dụng.');const count=Number(f.get('count'));const date=String(f.get('date'));const start=String(f.get('start'));const end=String(f.get('end'));const purpose=String(f.get('purpose')).trim();const existing=db.requests.find(r=>r.id===form.dataset.existing);if(existing&&existing.status!=='draft')return error('Phiếu đã được gửi, không thể chỉnh sửa.');if(!date||!start||!end)return error('Vui lòng nhập ngày và thời gian để lưu phiếu.');if(date<TODAY)return error('Vui lòng chọn ngày sử dụng từ hôm nay trở đi.');if(end<=start)return error('Giờ kết thúc phải sau giờ bắt đầu.');if(!Number.isInteger(count)||count<1||count>(kind==='room'?resource.seats:resource.available))return error(kind==='room'?'Số sinh viên phải nằm trong sức chứa của phòng.':'Số lượng không hợp lệ hoặc vượt số thiết bị trong danh mục.');if(intent==='pending'&&!f.get('commitment'))return error('Vui lòng xác nhận cam kết sử dụng.');const overlap=db.requests.filter(r=>r.id!==existing?.id&&r.resource===resource.id&&r.date===date&&!['cancelled','rejected','draft','completed'].includes(r.status)&&start<r.end&&end>r.start);if(kind==='room'&&(minutes(start)<minutes(ROOM_OPEN)||minutes(end)>minutes(ROOM_CLOSE)))return error('Giờ sử dụng phòng phải trong 07:00–18:00.');if(intent==='pending'&&kind==='room'&&!fitsInterval(roomFree(resource.id,date,existing?.id),start,end))return error('Phòng đã được giữ chỗ hoặc có lịch được duyệt trong khoảng này. Hãy chọn khung giờ còn trống.');if(intent==='pending'&&kind==='device'&&deviceFree(db,resource.id,date,start,end,existing?.id)<count)return error('Không đủ thiết bị trong khoảng thời gian đã chọn. Hãy giảm số lượng hoặc đổi giờ.');const item={id:existing?.id||`${kind==='room'?'PH':'TB'}-2026-${Date.now().toString().slice(-8)}`,kind,resource:resource.id,name:resource.name,date,start,end,purpose,status:intent,created:existing?.created||TODAY,...(kind==='room'?{students:count}:{quantity:count,returned:0})};if(existing)Object.assign(existing,item);else db.requests.push(item);if(!save())return;closeModal();filterTab=intent==='draft'?'draft':'all';if(route==='requests')render();else location.hash='#/requests';toast(intent==='draft'?'Đã lưu bản nháp. Phiếu chưa được gửi xét duyệt.':'Đã gửi đăng ký. Phiếu đang chờ cán bộ quản lý xét duyệt.');}
function detail(id){const r=db.requests.find(x=>x.id===id);if(!r)return;const fields=[['Mã phiếu',r.id],['Trạng thái',badge(r.status),true],['Nguồn lực',r.name],['Ngày sử dụng',fmtDate(r.date)],['Thời gian',`${r.start} – ${r.end}`],[r.kind==='room'?'Số sinh viên':'Số lượng',r.students||r.quantity],...(r.kind==='device'?[['Đã tiếp nhận trả',`${r.returned||0}/${r.quantity}`]]:[])];modal('Chi tiết phiếu đăng ký',`<dl class="detail-grid">${fields.map(([k,v,html])=>`<div><dt>${k}</dt><dd>${html?v:esc(v)}</dd></div>`).join('')}<div class="full"><dt>Mục đích sử dụng</dt><dd>${esc(r.purpose)}</dd></div></dl>${r.returnRequest?`<p class="detail-note">Đã gửi yêu cầu trả ${r.returnRequest.quantity} thiết bị (${r.returnRequest.good} tốt, ${r.returnRequest.damaged} hỏng, ${r.returnRequest.lost} mất). Chờ cán bộ quản lý tiếp nhận; chưa tự cộng vào kho.</p>`:''}${r.status==='rejected'?`<p class="detail-note">Lý do: ${esc(r.reason||'Vui lòng liên hệ bộ phận quản lý.')}</p>`:''}<div class="form-actions">${r.status==='draft'?`<button class="btn" data-edit="${esc(id)}">Chỉnh sửa bản nháp</button>`:''}${['pending','draft'].includes(r.status)?`<button class="btn" data-cancel="${esc(id)}">Hủy phiếu</button>`:''}${r.status==='ready'?`<button class="btn primary" data-receive="${esc(id)}">Xác nhận đã nhận thiết bị</button>`:''}${r.kind==='device'&&r.status==='borrowed'?`<button class="btn primary" data-return="${esc(id)}">Gửi yêu cầu trả</button>`:''}<button class="btn" data-action="close">Đóng</button></div>`);}
function cancelRequest(id){const r=db.requests.find(x=>x.id===id);if(!r||!['draft','pending'].includes(r.status))return;modal('Hủy phiếu đăng ký',`<p>Bạn muốn hủy phiếu <strong>${esc(r.id)}</strong> cho ${esc(r.name)}?</p><p class="form-note">Phiếu được giữ lại với trạng thái Đã hủy. Dữ liệu lịch sử không bị xóa.</p><div class="form-actions"><button class="btn" data-detail="${id}">Quay lại</button><button class="btn primary" data-confirm-cancel="${id}">Xác nhận hủy phiếu</button></div>`);}
function receive(id){const r=db.requests.find(x=>x.id===id);if(!r||r.status!=='ready')return;modal('Xác nhận nhận thiết bị',`<p>Kiểm tra đủ <strong>${r.quantity} ${esc(r.name)}</strong> và tình trạng thiết bị trước khi xác nhận.</p><p class="form-note">Chỉ xác nhận sau khi thực tế nhận thiết bị từ cán bộ quản lý.</p><div class="form-actions"><button class="btn" data-detail="${id}">Quay lại</button><button class="btn primary" data-confirm-receive="${id}">Tôi đã nhận đủ thiết bị</button></div>`);}
function returnForm(id){const r=db.requests.find(x=>x.id===id);if(!r||r.status!=='borrowed')return;modal('Gửi yêu cầu trả thiết bị',`<p class="form-note">${esc(r.name)} · Còn giữ ${r.quantity-r.returned} thiết bị. Hỗ trợ trả từng phần; số lượng kho chỉ cập nhật sau khi cán bộ quản lý tiếp nhận.</p><form id="return-form" data-id="${id}"><div class="form-grid">${[['good','Hoạt động tốt'],['damaged','Hỏng / cần kiểm tra'],['lost','Báo mất']].map(([n,l],i)=>`<div class="field ${i===2?'full':''}"><label for="return-${n}">${l}</label><input id="return-${n}" name="${n}" type="number" min="0" max="${r.quantity-r.returned}" value="${i===0?1:0}" required></div>`).join('')}<div class="field full"><label for="return-note">Ghi chú tình trạng</label><textarea id="return-note" name="notes" maxlength="500" placeholder="Ghi rõ trường hợp hỏng hoặc mất thiết bị"></textarea></div></div><p class="error" id="form-error" tabindex="-1" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close">Để sau</button><button class="btn primary" type="submit">Gửi yêu cầu trả</button></div></form>`);}
document.addEventListener('change',e=>{if(e.target.id==='log-used')toggleLogActual();});
function downloadRequests(csv){const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='phieu-cua-toi.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function closeMenu(){$('#sidebar').classList.remove('open');$('.mobile-backdrop')?.classList.remove('show');}
document.body.insertAdjacentHTML('beforeend','<div class="mobile-backdrop" data-action="close-menu"></div>');
document.addEventListener('click',event=>{const e=event.target.closest('button,[data-action]');if(!e)return;readLatest();const d=e.dataset;if(d.page){const target=d.pageTarget||route;pages[target]=Math.max(1,Number(d.page)||1);render();return;}if(d.day){selectedDay=d.day;render();return;}if(d.book)return book(d.book,d.kind,null,{date:d.date,start:d.start,end:d.end});if(d.detail)return detail(d.detail);if(d.tab){filterTab=d.tab;pages.requests=1;render();return;}if(d.edit){const r=db.requests.find(x=>x.id===d.edit);if(r)book(r.resource,r.kind,r);return;}if(d.cancel)return cancelRequest(d.cancel);if(d.confirmCancel){const r=db.requests.find(x=>x.id===d.confirmCancel);if(r&&['pending','draft'].includes(r.status)){r.status='cancelled';if(!save())return;closeModal();render();toast('Đã hủy phiếu. Lịch sử được giữ lại.');}return;}if(d.receive)return receive(d.receive);if(d.confirmReceive){const r=db.requests.find(x=>x.id===d.confirmReceive);if(r?.status==='ready'){r.status='borrowed';r.receivedAt=new Date().toISOString();if(!save())return;closeModal();render();toast('Đã xác nhận nhận thiết bị. Bạn có thể gửi yêu cầu trả thiết bị.');}return;}if(d.return)return returnForm(d.return);switch(d.action){case'clear-room-time':$('#room-start').value='';$('#room-end').value='';updateResourceResults();break;case'close':closeModal();break;case'menu':$('#sidebar').classList.toggle('open');$('.mobile-backdrop').classList.toggle('show');break;case'close-menu':closeMenu();break;case'notifications':modal('Thông báo & nhắc việc',`<div class="list-notices">${notices()}</div><p class="form-note">Các thông báo minh họa giúp bạn làm quen với giao diện. Trạng thái phiếu hiện tại được cập nhật trong Phiếu của tôi.</p>`);break;case'help':modal('Hướng dẫn sử dụng',`<div class="detail-note"><strong>01 · Đăng ký nguồn lực</strong><p>Chọn Đăng ký phòng hoặc Đăng ký thiết bị. Tìm nguồn lực, nhập thời gian, mục đích và gửi đăng ký. Có thể lưu nháp và chỉnh sửa trực tiếp bản nháp.</p><strong>02 · Theo dõi và nhận bàn giao</strong><p>Mở Phiếu của tôi để xem trạng thái. Phiếu chờ duyệt có thể hủy. Với thiết bị đã bàn giao, chọn xác nhận nhận đủ.</p><strong>03 · Ghi nhận sử dụng và trả thiết bị</strong><p>Thiết bị đang mượn có thể gửi yêu cầu trả từng phần, phân loại tốt, hỏng hoặc mất.</p></div><p class="form-note">Đây là frontend demo, không có bộ phận quản lý trực tuyến. Các phiếu mới sẽ ở trạng thái chờ xét duyệt. Dữ liệu chỉ lưu trên trình duyệt hiện tại.</p>`);break;case'profile':modal('Hồ sơ giảng viên',`<dl class="detail-grid"><div><dt>Họ và tên</dt><dd>Nguyễn Minh Anh</dd></div><div><dt>Mã cán bộ</dt><dd>GV-CNTT-028</dd></div><div><dt>Đơn vị</dt><dd>Khoa Công nghệ thông tin</dd></div><div><dt>Vai trò</dt><dd>Cán bộ / Giảng viên</dd></div></dl><p class="form-note">Tài khoản minh họa cho giao diện giảng viên. Chưa kết nối đăng nhập và dữ liệu thật của Nhà trường.</p>`);break;case'export':{const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const data=[['Mã phiếu','Nguồn lực','Ngày','Bắt đầu','Kết thúc','Trạng thái'],...db.requests.filter(r=>filterTab==='all'||(['room','device'].includes(filterTab)?r.kind===filterTab:r.status===filterTab)).map(r=>[r.id,r.name,fmtDate(r.date),r.start,r.end,statuses[r.status]?.[0]])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='phieu-cua-toi.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Đã tạo tệp CSV theo bộ lọc hiện tại.');break;}}});
document.addEventListener('submit',event=>{const form=event.target;if(!['resource-filter','list-filter','booking-form','return-form'].includes(form.id))return;event.preventDefault();readLatest();const f=new FormData(form);if(form.id==='resource-filter'){updateResourceResults();return;}if(form.id==='list-filter'){syncListFilterForm(form);render();return;}if(form.id==='booking-form')return bookingSubmit(form,event.submitter?.value||'pending');const r=db.requests.find(x=>x.id===form.dataset.id);if(!r)return;if(form.id==='return-form'){if(r.status!=='borrowed')return error('Phiếu không ở trạng thái cho phép yêu cầu trả.');const good=Number(f.get('good')),damaged=Number(f.get('damaged')),lost=Number(f.get('lost')),quantity=good+damaged+lost;const notes=String(f.get('notes')).trim();if(![good,damaged,lost].every(n=>Number.isInteger(n)&&n>=0)||quantity<1||quantity>r.quantity-r.returned)return error('Tổng số lượng trả phải từ 1 đến số thiết bị còn giữ.');r.returnRequest={quantity,good,damaged,lost,notes,date:TODAY};r.status='return_pending';if(!save())return;closeModal();render();toast('Đã gửi yêu cầu trả. Chờ cán bộ quản lý kiểm tra và tiếp nhận.');return;}});
document.addEventListener('change',e=>{if(e.target.closest('#resource-filter'))updateResourceResults();if(e.target.closest('#list-filter')&&e.target.tagName==='SELECT'){syncListFilterForm(e.target.closest('#list-filter'));render();}if(e.target.closest('#booking-form'))updateBookingAvailability();if(e.target.id==='calendar-date'&&e.target.value){selectedDay=e.target.value;render();}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#dialog').addEventListener('close',()=>previousFocus?.focus());
window.addEventListener('hashchange',async()=>{if($('#dialog').open)closeModal();selectedDay=TODAY;const next=lecturerRoute(location.hash.replace('#/','')||'overview');if(server){try{if(!await loadServerRoute(next))return;}catch(e){if(e.status===401)location.assign('login.html');toast(e.message);}}render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;readLatest();if($('#dialog').open){updateBookingAvailability();}else if(route==='rooms')updateResourceResults();else render();});
if(server)installServer();render();if(storageWarning)toast(storageWarning);
